import java.util.*;

public class Solution {
    static class UF {
        private final int[] pai, tam;
        private int componentes;

        UF(int n) {
            pai = new int[n];
            tam = new int[n];
            for (int i = 0; i < n; i++) { pai[i] = i; tam[i] = 1; }
            componentes = n;
        }

        // Iterativo com compressão: aponta cada nó do caminho direto para a raiz.
        int find(int x) {
            int r = x;
            while (pai[r] != r) r = pai[r];
            while (pai[x] != r) {
                int prox = pai[x];
                pai[x] = r;
                x = prox;
            }
            return r;
        }

        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (tam[ra] < tam[rb]) { int t = ra; ra = rb; rb = t; }
            pai[rb] = ra;
            tam[ra] += tam[rb];
            componentes--;
            return true;
        }

        int componentes() { return componentes; }
    }

    // Ordena por peso e aceita cada aresta que une componentes diferentes.
    static long mst(int n, int[][] arestas) {
        int[][] es = arestas.clone();
        Arrays.sort(es, Comparator.comparingInt(e -> e[2]));
        UF uf = new UF(n);
        long total = 0;
        for (int[] e : es) if (uf.union(e[0], e[1])) total += e[2];
        return uf.componentes() == 1 ? total : -1;
    }
}

