import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void unionFind() {
        var uf = new Solution.UF(5);
        assertTrue(uf.union(0, 1));
        assertTrue(uf.union(3, 4));
        assertFalse(uf.union(1, 0));
        assertEquals(3, uf.componentes());
        assertEquals(uf.find(0), uf.find(1));
        assertNotEquals(uf.find(0), uf.find(3));
    }

    @Test void mstPequena() {
        int[][] e = {{0, 1, 4}, {0, 2, 3}, {1, 2, 1}, {1, 3, 2}, {2, 3, 4}, {3, 4, 2}};
        assertEquals(8, Solution.mst(5, e));
    }

    @Test void desconexo() {
        assertEquals(-1, Solution.mst(4, new int[][]{{0, 1, 1}, {2, 3, 1}}));
        assertEquals(0, Solution.mst(1, new int[][]{}));
    }

    @Test void cadeiaLongaNaoEstoura() {
        int n = 300_000;
        var uf = new Solution.UF(n);
        for (int i = 1; i < n; i++) uf.union(i - 1, i);
        assertEquals(1, uf.componentes());
        assertEquals(uf.find(0), uf.find(n - 1));
    }

    @Test void grande() {
        var rnd = new Random(12);
        int n = 50_000;
        List<int[]> e = new ArrayList<>();
        for (int i = 1; i < n; i++) e.add(new int[]{i - 1, i, 1000});            // garante conexo
        for (int i = 0; i < 150_000; i++) e.add(new int[]{rnd.nextInt(n), rnd.nextInt(n), rnd.nextInt(1000)});
        long custo = Solution.mst(n, e.toArray(new int[0][]));
        assertTrue(custo > 0 && custo < 1000L * (n - 1));
    }
}
